_SCHEMAS = {
    item["function"]["name"]: item["function"].get("parameters", {})
    for item in TOOLS
}


def validate_arguments(name, arguments):
    """按 TOOLS 里的 schema 做显式参数校验，返回错误信息或 None。"""
    if not isinstance(arguments, dict):
        return "工具参数必须是 JSON 对象。"
    params = _SCHEMAS.get(name, {})
    properties = params.get("properties", {})
    required = params.get("required", [])
    missing = [key for key in required if key not in arguments]
    if missing:
        return f"工具 {name} 缺少必需参数：{missing}；需要 {required}。"
    unknown = [key for key in arguments if key not in properties]
    if unknown:
        return (
            f"工具 {name} 不支持参数：{unknown}；"
            f"支持的参数为 {sorted(properties)}。"
        )
    for key, value in arguments.items():
        if value is None:
            continue  # 可选参数显式传 null 视同未传
        expected = properties[key].get("type")
        if expected == "string" and not isinstance(value, str):
            return (
                f"工具 {name} 的参数 {key} 应为字符串，"
                f"实际为 {type(value).__name__}：{value!r}。"
            )
        if expected == "boolean" and not isinstance(value, bool):
            return (
                f"工具 {name} 的参数 {key} 应为布尔值 true/false（JSON 布尔），"
                f"不要传字符串 \"true\"/\"false\"；实际为 {type(value).__name__}：{value!r}。"
            )
        if expected == "integer" and (isinstance(value, bool) or not isinstance(value, int)):
            return (
                f"工具 {name} 的参数 {key} 应为整数，"
                f"实际为 {type(value).__name__}：{value!r}。"
            )
        if expected == "number" and (isinstance(value, bool) or not isinstance(value, (int, float))):
            return (
                f"工具 {name} 的参数 {key} 应为数字，"
                f"实际为 {type(value).__name__}：{value!r}。"
            )
    return None


REASON_CODES = {
    ERR_ARG: "arg_error",
    ERR_NOT_EXEC: "not_executed",
    ERR_NOT_FOUND: "not_found",
    ERR_FAIL: "exec_failed",
}


def _reason_code_from_text(text, ok):
    if ok:
        return "ok"
    for prefix, code in REASON_CODES.items():
        if isinstance(text, str) and text.startswith(prefix):
            return code
    return "failed"


def execute_tool_ex(name, arguments):
    """执行工具并返回 (ok, 回显文本, meta)。

    ``ok`` 不再只看回显前缀：
      * bash 的**非 0 退出码**现在直接判定为失败（旧版只在尾部追加“[退出码 1]”，
        而 ``is_error_result`` 只看前缀，于是 ``grep -c`` 无匹配 → ``ok=True``）；
      * ``meta["reason_code"]`` 供 agent 层写进轨迹，让 G5/G7 这类判据不必读中文 prose。
    """
    meta = {"tool": name}
    if name not in tools:
        text = f"{ERR_ARG} 工具不存在：{name}；可用工具为 {sorted(tools)}。"
        meta["reason_code"] = "tool_not_found"
        meta["ok"] = False
        return False, text, meta
    error = validate_arguments(name, arguments)
    if error:
        text = f"{ERR_ARG} {error}"
        meta["reason_code"] = "arg_error"
        meta["ok"] = False
        return False, text, meta
    try:
        if name == "bash":
            res, extra = _bash_run(**arguments)
            meta.update(extra)
        else:
            res = tools[name](**arguments)
    except TypeError as exc:
        text = f"{ERR_ARG} 参数与工具签名不匹配：{type(exc).__name__}: {exc}"
        meta["reason_code"] = "arg_error"
        meta["ok"] = False
        return False, text, meta
    except Exception as exc:
        text = f"{ERR_FAIL} 工具 {name} 执行异常：{type(exc).__name__}: {exc}"
        meta["reason_code"] = "exec_failed"
        meta["ok"] = False
        return False, text, meta
    if not isinstance(res, str):
        res = str(res)
    ok = not is_error_result(res)
    meta.setdefault("reason_code", _reason_code_from_text(res, ok))
    meta["ok"] = ok
    return ok, res, meta


def execute_tool_detailed(name, arguments):
    """执行工具并返回 (ok, 回显文本)（保持旧签名）。"""
    ok, text, _meta = execute_tool_ex(name, arguments)
    return ok, text


def execute_tool(name, arguments):
    """兼容旧接口：只返回回显文本。"""
    return execute_tool_detailed(name, arguments)[1]

