def _bash_run(command):
    """执行 shell 命令，返回 (回显文本, meta)。meta 里带 exit_code / reason_code。"""
    meta = {"tool": "bash"}
    try:
        res = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=120
        )
        output = (res.stdout or "") + (res.stderr or "")
        meta["exit_code"] = res.returncode
        meta["stdout_chars"] = len(res.stdout or "")
        meta["stderr_chars"] = len(res.stderr or "")
        if res.returncode == 0:
            return output, meta
        meta["reason_code"] = "nonzero_exit"
        return (
            f"{ERR_FAIL} 退出码 {res.returncode}：命令【已实际执行】，但以非 0 退出码结束。"
            "非 0 只代表该命令自身的成败判定（例如 grep 无匹配通常返回 1、test 条件为假返回 1），"
            "不等于命令没有跑；请据实描述结果，不要写成“通过 / 成功 / 已验证”。\n"
            f"--- 命令输出开始（stdout+stderr）---\n{output}--- 命令输出结束 ---"
        ), meta
    except subprocess.TimeoutExpired as exc:
        meta["reason_code"] = "timeout"
        return f"{ERR_FAIL} 命令超时（120 秒）被终止：{type(exc).__name__}: {exc}", meta
    except Exception as exc:
        meta["reason_code"] = "exec_failed"
        return f"{ERR_FAIL} 命令执行失败：{type(exc).__name__}: {exc}", meta


def bash(command):
    return _bash_run(command)[0]

